import { addDays, addMonths, monthKey, shiftMonth } from "../dates";
import type { RhoAccount, RhoTransaction } from "../rho/schema";
import type { Category, FindingKind } from "../types";
import { createRng, type Rng } from "./rng";

/**
 * "Taco Robotics, Inc." — a synthetic seed-stage startup in Rho's wire format.
 * Every row is fake and generated by this file. Waste is planted on purpose and
 * recorded in `truth` so detectors can be scored; negative controls must NOT fire.
 */

export interface PlantedWaste {
  kind: FindingKind;
  vendorKeys: string[];
  monthlyCents: number;
  oneTimeCents: number;
  note: string;
}

export interface DemoCompany {
  name: string;
  asOf: string;
  accounts: RhoAccount[];
  transactions: RhoTransaction[];
  truth: PlantedWaste[];
  /** Expected category per vendor key, for scoring categorization. */
  categoryLabels: Record<string, Category>;
}

export interface DemoOptions {
  seed?: number;
  asOf?: string;
  months?: number;
  /** "noisy" wraps descriptors in processor prefixes and store numbers, like real card feeds. */
  noise?: "clean" | "noisy";
}

const CHECKING = "acc_taco_checking";
const CREDIT = "acc_taco_card";
const SAVINGS = "acc_taco_savings";

interface Sub {
  descriptor: string;
  cardholder: string;
  dollars: (monthIndex: number, monthsTotal: number) => number;
  day: number;
  /** Months (0-based from start) when the subscription bills; default all. */
  activeFrom?: number;
  annualMonth?: number;
}

const SUBSCRIPTIONS: readonly Sub[] = [
  { descriptor: "SLACK TECHNOLOGIES", cardholder: "Maya Thompson", dollars: () => 480, day: 3 },
  { descriptor: "ZOOM.US 888-799-9666", cardholder: "Maya Thompson", dollars: () => 149.9, day: 5 },
  { descriptor: "CISCO WEBEX", cardholder: "Andrew Collins", dollars: () => 90, day: 9 },
  { descriptor: "LOOM.COM", cardholder: "Maya Thompson", dollars: () => 60, day: 11 },
  { descriptor: "GOOGLE *GSUITE_tacorobotics", cardholder: "Maya Thompson", dollars: () => 864, day: 1 },
  { descriptor: "NOTION LABS", cardholder: "Daniel Rivera", dollars: () => 96, day: 14 },
  { descriptor: "ATLASSIAN *CONFLUENCE", cardholder: "Daniel Rivera", dollars: () => 57, day: 15, activeFrom: 4 },
  { descriptor: "LINEAR", cardholder: "Daniel Rivera", dollars: () => 64, day: 7 },
  { descriptor: "GITHUB.COM", cardholder: "Daniel Rivera", dollars: () => 210, day: 2 },
  { descriptor: "DATADOG INC", cardholder: "Daniel Rivera", dollars: (i, n) => (i < n - 4 ? 2_400 : 3_600), day: 6 },
  { descriptor: "SENTRY", cardholder: "Daniel Rivera", dollars: () => 26, day: 19 },
  { descriptor: "VERCEL INC", cardholder: "Daniel Rivera", dollars: () => 20, day: 12 },
  { descriptor: "FIGMA", cardholder: "Priya Shah", dollars: () => 225, day: 17 },
  { descriptor: "MIRO.COM", cardholder: "Priya Shah", dollars: () => 150, day: 18 },
  { descriptor: "CALENDLY", cardholder: "Priya Shah", dollars: () => 48, day: 20 },
  { descriptor: "HUBSPOT INC", cardholder: "Sofia Martin", dollars: () => 800, day: 8 },
  { descriptor: "INTERCOM", cardholder: "Sofia Martin", dollars: () => 395, day: 10 },
  { descriptor: "SALESFORCE.COM", cardholder: "Sofia Martin", dollars: () => 1_650, day: 13, activeFrom: 3 },
  { descriptor: "1PASSWORD", cardholder: "Maya Thompson", dollars: () => 48, day: 21 },
  { descriptor: "DOCUSIGN", cardholder: "Sofia Martin", dollars: () => 600, day: 2, annualMonth: 5 },
];

const TEAM_TRAVEL = ["Maya Thompson", "Daniel Rivera", "Sofia Martin", "Andrew Collins"] as const;
/** Priya's last non-subscription purchase is in this month (0-based); afterwards her card only pays SaaS. */
const PRIYA_LAST_ACTIVE_MONTH = 7;
const NOISE_PREFIXES = ["SQ *", "TST* ", "PAYPAL *", "SP * "];

export const DEMO_CATEGORY_LABELS: Record<string, Category> = {
  slack: "software", zoom: "software", webex: "software", loom: "software", google_workspace: "software",
  notion: "software", confluence: "software", linear: "software", github: "software", datadog: "software",
  sentry: "software", vercel: "cloud", figma: "software", miro: "software", calendly: "software",
  hubspot: "software", salesforce: "software", intercom: "software", one_password: "software", docusign: "software",
  canva: "software", aws: "cloud", openai: "ai_api", gusto: "payroll", brazos_properties: "rent",
  vouch: "insurance", pilot: "legal_accounting", stripe: "revenue", uber: "travel", doordash: "meals",
  united: "travel", bank_fees: "fees", blue_bottle: "meals", teamline_software: "software",
};

const dollarsToCents = (d: number) => Math.round(d * 100);

export function generateDemoCompany({ seed = 42, asOf = "2026-10-26", months = 12, noise = "clean" }: DemoOptions = {}): DemoCompany {
  const rng = createRng(seed);
  const rows: RhoTransaction[] = [];
  const startMonth = shiftMonth(monthKey(asOf), -months);
  let n = 0;

  const descriptor = (raw: string) =>
    noise === "noisy" && rng.chance(0.5) ? `${rng.pick(NOISE_PREFIXES)}${raw} #${rng.int(100, 9999)}` : raw;

  function push(date: string, cents: number, counterparty: string, type: string, account: string, cardholder?: string, status: RhoTransaction["status"] = "settled") {
    if (date > asOf) return;
    n += 1;
    const id = `tx_${String(n).padStart(5, "0")}`;
    rows.push({
      id,
      money_movement_id: `mm_${id}`,
      account_id: account,
      account_name: account === CREDIT ? "Rho Card" : account === SAVINGS ? "Savings" : "Operating",
      account_type: account === CREDIT ? "credit" : account === SAVINGS ? "savings" : "checking",
      amount: { amount: cents, currency: "USD" },
      status,
      transaction_type: type,
      counterparty_name: counterparty,
      initiated_at: `${date}T15:00:00Z`,
      posted_at: status === "settled" ? `${date}T18:00:00Z` : null,
      card_id: cardholder ? `card_${cardholder.split(" ")[0]!.toLowerCase()}` : null,
      card_name: cardholder ? `${cardholder.split(" ")[0]}'s card` : null,
      user_full_name: cardholder ?? null,
    });
  }

  for (let i = 0; i <= months; i++) {
    const month = shiftMonth(startMonth, i);
    const day = (d: number) => `${month}-${String(d).padStart(2, "0")}`;
    let cardTotal = 0;
    const card = (d: string, dollars: number, raw: string, holder: string) => {
      const cents = dollarsToCents(dollars);
      if (d <= asOf) cardTotal += cents;
      push(d, -cents, descriptor(raw), "card_debit", CREDIT, holder);
    };

    // Payroll twice a month, rent, insurance, bookkeeping.
    push(day(1), -dollarsToCents(38_400 + rng.int(-300, 300)), "GUSTO PAYROLL 8473", "ach_debit", CHECKING);
    push(day(15), -dollarsToCents(38_400 + rng.int(-300, 300)), "GUSTO PAYROLL 8473", "ach_debit", CHECKING);
    push(day(1), -dollarsToCents(9_000), "BRAZOS PROPERTIES RENT", "ach_debit", CHECKING);
    push(day(4), -dollarsToCents(1_100), "VOUCH INSURANCE", "ach_debit", CHECKING);
    push(day(12), -dollarsToCents(900), "PILOT.COM BOOKKEEPING", "ach_debit", CHECKING);

    // Revenue: weekly Stripe payouts, growing.
    for (const d of [3, 10, 17, 24]) {
      push(day(d), dollarsToCents(4_000 + i * 250 + rng.int(-400, 400)), "STRIPE TRANSFER", "ach_credit", CHECKING);
    }

    // Usage-based cloud and AI spend: grows, but is NOT price creep (negative control).
    card(day(3), 3_000 + i * 150 + rng.int(-120, 120), "AWS EMEA", "Daniel Rivera");
    card(day(4), 400 + i * 110 + rng.int(-60, 60), "OPENAI *CHATGPT API", "Daniel Rivera");

    for (const s of SUBSCRIPTIONS) {
      if (s.activeFrom !== undefined && i < s.activeFrom) continue;
      if (s.annualMonth !== undefined && i % 12 !== s.annualMonth) continue;
      card(addDays(day(s.day), rng.int(-1, 1)), s.dollars(i, months), s.descriptor, s.cardholder);
    }

    // Everyday card spend for active people. Priya stops after PRIYA_LAST_ACTIVE_MONTH.
    const travellers = i <= PRIYA_LAST_ACTIVE_MONTH ? [...TEAM_TRAVEL, "Priya Shah"] : [...TEAM_TRAVEL];
    for (const holder of travellers) {
      card(day(rng.int(5, 25)), rng.int(18, 60), "DOORDASH", holder);
      if (rng.chance(0.4)) card(day(rng.int(5, 25)), rng.int(15, 45), "UBER TRIP", holder);
    }
    if (i % 3 === 1) card(day(rng.int(6, 20)), rng.int(380, 640), "UNITED AIRLINES", rng.pick(TEAM_TRAVEL));
    if (i === 6) card(day(22), 7.85, "BLUE BOTTLE COFFEE", "Priya Shah");

    // Planted double charge: Canva charged twice in one month.
    if (i === months - 2) {
      card(day(10), 119.99, "CANVA", "Sofia Martin");
      card(day(11), 119.99, "CANVA", "Sofia Martin");
    }

    // Pay off the card from checking. Both legs are transfers and must not count as burn.
    const payDay = addMonths(day(28), 0);
    push(payDay, -cardTotal, "RHO CARD PAYMENT", "credit_repayment", CHECKING);
    push(payDay, cardTotal, "RHO CARD PAYMENT", "credit_repayment", CREDIT);
  }

  // Edge cases the pipeline must handle.
  push(addDays(asOf, -40), -dollarsToCents(50_000), "TRANSFER TO SAVINGS", "internal_transfer", CHECKING);
  push(addDays(asOf, -40), dollarsToCents(50_000), "TRANSFER FROM OPERATING", "internal_transfer", SAVINGS);
  push(addDays(asOf, -20), -dollarsToCents(2_400), "TEAMLINE SOFTWARE INC", "ach_debit", CHECKING, undefined, "failed");
  push(addDays(asOf, -2), -dollarsToCents(310), "GITHUB.COM", "card_debit", CREDIT, "Daniel Rivera", "pending");

  const accounts: RhoAccount[] = [
    { id: CHECKING, account_type: "checking", account_name: "Operating", balance: { amount: dollarsToCents(842_350), currency: "USD" } },
    { id: SAVINGS, account_type: "savings", account_name: "Savings", balance: { amount: dollarsToCents(110_000), currency: "USD" } },
    { id: CREDIT, account_type: "credit", account_name: "Rho Card", balance: { amount: -dollarsToCents(9_120), currency: "USD" } },
  ];

  const truth: PlantedWaste[] = [
    { kind: "duplicate_tools", vendorKeys: ["webex", "zoom"], monthlyCents: dollarsToCents(90), oneTimeCents: 0, note: "Zoom and Webex both paid for video meetings" },
    { kind: "duplicate_tools", vendorKeys: ["confluence", "notion"], monthlyCents: dollarsToCents(57), oneTimeCents: 0, note: "Confluence added while Notion is the wiki" },
    { kind: "price_creep", vendorKeys: ["datadog"], monthlyCents: dollarsToCents(1_200), oneTimeCents: 0, note: "Datadog $2,400 → $3,600" },
    { kind: "duplicate_tools", vendorKeys: ["hubspot", "salesforce"], monthlyCents: dollarsToCents(800), oneTimeCents: 0, note: "Salesforce added; HubSpot never cancelled" },
    { kind: "zombie", vendorKeys: ["calendly", "figma", "miro"], monthlyCents: dollarsToCents(423), oneTimeCents: 0, note: "Priya stopped spending; her card still pays three tools" },
    { kind: "duplicate_charge", vendorKeys: ["canva"], monthlyCents: 0, oneTimeCents: dollarsToCents(119.99), note: "Canva charged twice" },
  ];

  return { name: "Taco Robotics, Inc.", asOf, accounts, transactions: rows, truth, categoryLabels: DEMO_CATEGORY_LABELS };
}
